def selection_sort(arr: list) -> list:
    """Ordenamiento por selección O(n²)."""
    arr = arr[:]
    n = len(arr)
    for i in range(n):
        min_idx = i
        for j in range(i + 1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j
        arr[i], arr[min_idx] = arr[min_idx], arr[i]
    return arr

print(selection_sort([64, 25, 12, 22, 11]))

def bubble_sort(arr: list) -> list:
    """Ordenamiento de burbuja O(n²)."""
    arr = arr[:]
    n = len(arr)
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

print(bubble_sort([64, 34, 25, 12, 22, 11, 90]))

def counting_sort(arr: list, max_val: int) -> list:
    """Counting sort O(n + k), para enteros pequeños."""
    count = [0] * (max_val + 1)
    for x in arr:
        count[x] += 1
    resultado = []
    for val, freq in enumerate(count):
        resultado.extend([val] * freq)
    return resultado

print(counting_sort([4, 2, 2, 8, 3, 3, 1], 8))

def quick_sort(arr: list) -> list:
    """Quick sort O(n log n) promedio."""
    if len(arr) <= 1:
        return arr
    pivote = arr[len(arr) // 2]
    menores = [x for x in arr if x < pivote]
    iguales = [x for x in arr if x == pivote]
    mayores = [x for x in arr if x > pivote]
    return quick_sort(menores) + iguales + quick_sort(mayores)

print(quick_sort([3, 6, 8, 10, 1, 2, 1]))

def merge_sort(arr: list) -> list:
    """Merge sort O(n log n)."""
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    izq = merge_sort(arr[:mid])
    der = merge_sort(arr[mid:])
    return merge(izq, der)

def merge(izq: list, der: list) -> list:
    resultado = []
    i = j = 0
    while i < len(izq) and j < len(der):
        if izq[i] <= der[j]:
            resultado.append(izq[i]); i += 1
        else:
            resultado.append(der[j]); j += 1
    resultado.extend(izq[i:])
    resultado.extend(der[j:])
    return resultado

